DECLARE
  v_store_id uuid;
  v_status text;
  v_service_number text;
  v_supplier text;
  v_total numeric;
  v_currency text;
  v_snapshot jsonb;
  v_payments integer;
  v_distributions integer;
  v_posted integer;
  v_caller_uid uuid := CASE
    WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid())
    ELSE auth.uid()
  END;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_service_id::text));

  SELECT store_id, status, service_number, supplier, total_amount, currency
  INTO v_store_id, v_status, v_service_number, v_supplier, v_total, v_currency
  FROM received_services WHERE id = p_service_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'ERR_SERVICE_NOT_FOUND'; END IF;

  -- Autorización del ACTOR sobre la tienda REAL del documento (patrón ADN-009).
  IF v_caller_uid IS NULL OR NOT public.can_manage_store_as(v_caller_uid, v_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;

  -- Solo borradores: los documentos activos se ANULAN (con asiento de
  -- reversión), jamás se eliminan físicamente.
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'ERR_NOT_DRAFT: solo los documentos en Borrador pueden eliminarse (estado actual: %)', v_status;
  END IF;

  -- Dependencias incompatibles con el borrado físico.
  SELECT COUNT(*) INTO v_payments
    FROM payment_transactions
   WHERE ref_type = 'service' AND ref_id = p_service_id;
  IF v_payments > 0 THEN
    RAISE EXCEPTION 'ERR_HAS_PAYMENTS: el borrador tiene % pago(s) registrado(s); cáncelalo en su lugar', v_payments;
  END IF;

  SELECT COUNT(*) INTO v_distributions
    FROM service_cost_distributions
   WHERE service_id = p_service_id;
  IF v_distributions > 0 THEN
    RAISE EXCEPTION 'ERR_HAS_DISTRIBUTIONS: el borrador tiene distribuciones de costo calculadas; cáncelalo en su lugar';
  END IF;

  -- Defensa contable (en un borrador sano no existen asientos).
  SELECT COUNT(*) INTO v_posted
    FROM fin_entries
   WHERE document_type = 'SERVICIO_RECIBIDO' AND document_id = p_service_id;
  IF v_posted > 0 THEN
    RAISE EXCEPTION 'ERR_ALREADY_POSTED: el documento tiene asientos contables; anúlalo en su lugar';
  END IF;

  -- Trazabilidad PRIMERO (sobrevive al DELETE del documento).
  SELECT to_jsonb(rs.*) INTO v_snapshot
    FROM received_services rs WHERE rs.id = p_service_id;

  INSERT INTO audit_logs (user_id, store_id, action, table_name, record_id, metadata)
  VALUES (v_caller_uid, v_store_id, 'SERVICE_DRAFT_DELETED', 'received_services', p_service_id,
    jsonb_build_object(
      'service_number', v_service_number,
      'supplier', v_supplier,
      'total_amount', v_total,
      'currency', v_currency,
      'reason', p_reason,
      'snapshot', v_snapshot
    ));

  DELETE FROM received_services WHERE id = p_service_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'deleted', true,
    'service_number', v_service_number
  );
END;

DECLARE
  v_caller uuid := CASE WHEN auth.role() = 'service_role' THEN coalesce(p_user_id, auth.uid()) ELSE auth.uid() END;
  v_ob public.fin_opening_balances%ROWTYPE;
  v_entry uuid; v_sense text; v_cat public.fin_categories%ROWTYPE;
  v_amount_cup numeric;
BEGIN
  SELECT * INTO v_ob FROM public.fin_opening_balances WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ERR_OPENING_NOT_FOUND'; END IF;
  IF v_caller IS NULL OR NOT public.has_store_role_as(v_caller, v_ob.store_id, ARRAY['admin']) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;
  IF v_ob.status <> 'draft' THEN RAISE EXCEPTION 'ERR_OPENING_NOT_DRAFT (estado: %)', v_ob.status; END IF;
  SELECT * INTO v_cat FROM public.fin_categories WHERE code = v_ob.category_code;
  v_amount_cup := round(CASE WHEN v_ob.currency = 'CUP' THEN v_ob.amount
                             ELSE v_ob.amount * v_ob.exchange_rate END, 2);

  IF v_ob.amount = 0 THEN
    -- M-015 · Declaración de apertura en cero: documenta la VERIFICACIÓN de
    -- que la cuenta no tenía saldo al corte (sin inventar importes). El
    -- asiento no lleva movimientos: no altera saldos ni ecuación contable.
    IF NULLIF(btrim(coalesce(v_ob.notes, '')), '') IS NULL THEN
      RAISE EXCEPTION 'ERR_OPENING_ZERO_NEEDS_NOTES: la declaración en cero exige justificación/documento de verificación';
    END IF;
    INSERT INTO public.fin_entries (
      store_id, document_type, document_id, document_number, event, economic_date,
      rule_version_id, description, created_by)
    VALUES (v_ob.store_id, 'APERTURA_FIN', NULL, 'APERTURA-' || v_ob.as_of_date, 'apertura',
            v_ob.as_of_date, NULL,
            'Declaración de apertura en cero: ' || v_cat.name, v_caller)
    RETURNING id INTO v_entry;
    UPDATE public.fin_opening_balances
    SET status = 'applied', applied_at = now(), entry_id = v_entry, authorized_by = v_caller
    WHERE id = p_id;
    INSERT INTO public.audit_logs (action, table_name, record_id, store_id, user_id, metadata)
    VALUES ('FIN_OPENING_APPLIED_ZERO', 'fin_opening_balances', p_id, v_ob.store_id, v_caller,
            jsonb_build_object('category', v_ob.category_code, 'amount_cup', 0,
                               'as_of', v_ob.as_of_date, 'cero_documentado', true,
                               'notas', v_ob.notes));
    RETURN jsonb_build_object('status', 'success', 'entry_id', v_entry, 'cero', true);
  END IF;

  IF v_cat.clase IN ('activo', 'gasto') THEN v_sense := 'debito'; ELSE v_sense := 'credito'; END IF;
  INSERT INTO public.fin_entries (
    store_id, document_type, document_id, document_number, event, economic_date,
    rule_version_id, description, created_by)
  VALUES (v_ob.store_id, 'APERTURA_FIN', NULL, 'APERTURA-' || v_ob.as_of_date, 'apertura',
          v_ob.as_of_date, NULL, 'Saldo inicial: ' || v_cat.name, v_caller)
  RETURNING id INTO v_entry;
  INSERT INTO public.fin_movements (
    entry_id, store_id, category_code, sense, amount, currency, exchange_rate,
    economic_date, document_number, description, currency_origin, traza)
  VALUES (v_entry, v_ob.store_id, v_ob.category_code, v_sense, v_ob.amount,
          CASE WHEN v_ob.currency = 'CUP' THEN 'CUP' ELSE v_ob.currency END,
          CASE WHEN v_ob.currency = 'CUP' THEN 1 ELSE v_ob.exchange_rate END,
          v_ob.as_of_date, 'APERTURA-' || v_ob.as_of_date,
          'Saldo inicial: ' || v_cat.name, v_ob.currency,
          jsonb_build_object('origen', 'saldo_inicial'));
  UPDATE public.fin_opening_balances
  SET status = 'applied', applied_at = now(), entry_id = v_entry, authorized_by = v_caller
  WHERE id = p_id;
  INSERT INTO public.audit_logs (action, table_name, record_id, store_id, user_id, metadata)
  VALUES ('FIN_OPENING_APPLIED', 'fin_opening_balances', p_id, v_ob.store_id, v_caller,
          jsonb_build_object('category', v_ob.category_code, 'amount_cup', v_amount_cup,
                             'as_of', v_ob.as_of_date));
  RETURN jsonb_build_object('status', 'success', 'entry_id', v_entry);
END

DECLARE
  v_rule public.fin_rule_versions%ROWTYPE;
  v_metrics jsonb; v_movs jsonb; t jsonb;
  v_entry_id uuid; v_debit numeric := 0; v_credit numeric := 0;
  v_store uuid; v_docnum text; v_date date;
  v_gen uuid;
BEGIN
  IF p_document_id IS NULL THEN RAISE EXCEPTION 'ERR_NO_DOCUMENT'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('fin:' || p_doctype || ':' || p_document_id::text));

  v_metrics := public.fin_compute_metrics(p_doctype, p_document_id, p_event, p_payment_ref);
  v_store := (v_metrics ->> 'store_id')::uuid;
  v_docnum := v_metrics ->> 'doc_number';
  v_date := (v_metrics ->> 'economic_date')::date;

  -- Generación destino: explícita (construcción de candidata) o la ACTIVA.
  v_gen := coalesce(p_generation_id, public.fin_active_generation(v_store));

  -- Idempotencia (doble clic, reintento, concurrencia) DENTRO de la generación
  IF EXISTS (
    SELECT 1 FROM public.fin_entries e
    WHERE e.document_type = p_doctype AND e.document_id = p_document_id
      AND e.event = p_event AND e.payment_ref IS NOT DISTINCT FROM p_payment_ref
      AND e.generation_id IS NOT DISTINCT FROM v_gen
  ) THEN
    RETURN NULL;
  END IF;

  v_rule := public.fin_resolve_rule(p_doctype, v_store);
  IF v_rule.id IS NULL THEN RETURN NULL; END IF;               -- sin regla activa: no contabiliza

  v_movs := public.fin_apply_templates(v_rule.movements, p_event, v_metrics);
  IF v_movs = '[]'::jsonb THEN RETURN NULL; END IF;            -- regla sin efectos para este doc

  SELECT coalesce(sum(CASE WHEN m ->> 'sentido' = 'debito' THEN (m ->> 'amount')::numeric ELSE 0 END), 0),
         coalesce(sum(CASE WHEN m ->> 'sentido' = 'credito' THEN (m ->> 'amount')::numeric ELSE 0 END), 0)
    INTO v_debit, v_credit
  FROM jsonb_array_elements(v_movs) m;

  IF p_event NOT IN ('apertura', 'ajuste_manual') AND abs(v_debit - v_credit) > 0.01 THEN
    RAISE EXCEPTION 'ERR_UNBALANCED: débitos=% créditos=% (tipo=% doc=%)',
      v_debit, v_credit, p_doctype, p_document_id;
  END IF;

  INSERT INTO public.fin_entries (
    store_id, document_type, document_id, document_number, event, payment_ref,
    economic_date, rule_version_id, movements_snapshot, description, created_by,
    generation_id)
  VALUES (
    v_store, p_doctype, p_document_id, v_docnum, p_event, p_payment_ref,
    v_date, v_rule.id, v_movs,
    v_metrics ->> 'descripcion_documento', p_actor, v_gen)
  RETURNING id INTO v_entry_id;

  FOR t IN SELECT * FROM jsonb_array_elements(v_movs) LOOP
    INSERT INTO public.fin_movements (
      entry_id, store_id, category_code, sense, amount, currency, exchange_rate,
      economic_date, document_number, description, currency_origin, amount_origin, traza)
    VALUES (
      v_entry_id, v_store, t ->> 'categoria', t ->> 'sentido', (t ->> 'amount')::numeric,
      'CUP', 1, v_date, v_docnum, v_metrics ->> 'descripcion_documento',
      t ->> 'currency_origin', (t ->> 'amount_origin')::numeric, t -> 'traza');
  END LOOP;

  RETURN v_entry_id;
END

DECLARE
  e record; m record; v_new uuid; v_count integer := 0;
  v_residual numeric;
  v_store uuid; v_gen uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('fin:' || p_doctype || ':' || p_document_id::text));

  v_store := (SELECT store_id FROM public.fin_entries
              WHERE document_type = p_doctype AND document_id = p_document_id
              ORDER BY posted_at LIMIT 1);
  IF v_store IS NULL THEN RETURN 0; END IF;
  v_gen := coalesce(p_generation_id, public.fin_active_generation(v_store));

  FOR e IN
    SELECT * FROM public.fin_entries
    WHERE document_type = p_doctype AND document_id = p_document_id
      AND status = 'posted' AND event IN ('reconocimiento', 'pago')
      AND generation_id IS NOT DISTINCT FROM v_gen
    ORDER BY posted_at
  LOOP
    -- ¿ya tiene anulación? (idempotencia dentro de la generación)
    IF EXISTS (SELECT 1 FROM public.fin_entries x
               WHERE x.reversal_of = e.id) THEN
      v_residual := public.fin_entry_reversal_residual(e.id);
      IF v_residual <= 0.01 THEN
        CONTINUE;
      END IF;
      RAISE EXCEPTION 'ERR_PARTIAL_REVERSAL_PENDING: el asiento % (doc % %) tiene reversiones parciales enlazadas y un residual de % CUP sin compensar. Regularice primero el residual contable (asiento explícito documentado, p. ej. runbook RECT004 §regularización); después la anulación funcionará por el cauce ordinario. El canal _safe registra este intento en fin_posting_errors.',
        e.id, p_doctype, p_document_id, v_residual;
    END IF;
    INSERT INTO public.fin_entries (
      store_id, document_type, document_id, document_number, event, payment_ref,
      economic_date, rule_version_id, movements_snapshot, reversal_of, description, created_by,
      generation_id)
    VALUES (
      e.store_id, e.document_type, e.document_id, e.document_number, 'anulacion',
      e.payment_ref, e.economic_date, e.rule_version_id, e.movements_snapshot, e.id,
      'Anulación: ' || coalesce(e.description, ''), e.created_by, v_gen)
    RETURNING id INTO v_new;
    FOR m IN SELECT * FROM public.fin_movements WHERE entry_id = e.id LOOP
      INSERT INTO public.fin_movements (
        entry_id, store_id, category_code, sense, amount, currency, exchange_rate,
        economic_date, document_number, description, currency_origin, amount_origin, traza)
      VALUES (
        v_new, m.store_id, m.category_code,
        CASE WHEN m.sense = 'debito' THEN 'credito' ELSE 'debito' END,
        m.amount, m.currency, m.exchange_rate, m.economic_date, m.document_number,
        'Anulación: ' || coalesce(m.description, ''), m.currency_origin,
        m.amount_origin,
        m.traza || jsonb_build_object('anulacion_de', m.id));
    END LOOP;
    UPDATE public.fin_entries SET status = 'reversed' WHERE id = e.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END

DECLARE
  v_gen uuid := coalesce(p_generation_id, public.fin_active_generation(p_store_id));
  v_entry_id uuid;
  v_expected int := jsonb_array_length(p_movements);
  v_debit numeric := 0; v_credit numeric := 0;
  v_n_mov int := 0; v_saldo numeric := 0;
  v_m jsonb; t jsonb; r record;
  v_audit uuid;
  v_count int;
  v_coherente boolean;
  v_antes int := 0;
BEGIN
  -- ACL pura (patrón fin_generation_build / fin_rectify_*): el canal de
  -- ejecución se restringe por GRANT a service_role (§4); sin chequeo interno
  -- de auth.role() — mismo diseño que el resto del motor.
  IF p_store_id IS NULL OR p_document_number IS NULL OR p_document_type IS NULL
     OR p_economic_date IS NULL OR p_movements IS NULL
     OR jsonb_typeof(p_movements) <> 'array' OR v_expected = 0 THEN
    RAISE EXCEPTION 'ERR_RECT_PARAMS_INVALIDOS: store/document_number/type/date/movements[] no vacíos';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.stores s WHERE s.id = p_store_id) THEN
    RAISE EXCEPTION 'ERR_STORE_NOT_FOUND: tienda %', p_store_id;
  END IF;
  IF v_gen IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.fin_posting_generations g
       WHERE g.id = v_gen AND g.store_id = p_store_id
         AND g.status IN ('active', 'building', 'candidate')) THEN
    RAISE EXCEPTION 'ERR_GENERACION_NO_ENCONTRADA: generación destino % inválida para la tienda', v_gen;
  END IF;

  -- Serialización por (tienda, documento): idempotencia bajo concurrencia.
  PERFORM pg_advisory_xact_lock(hashtext('fin_rect:' || p_store_id::text || ':' || p_document_number));

  -- Validación estructural de movements — fail-closed ANTES de escribir nada.
  FOR v_m IN SELECT * FROM jsonb_array_elements(p_movements) LOOP
    IF v_m ->> 'categoria' IS NULL OR NOT EXISTS (
         SELECT 1 FROM public.fin_categories c
         WHERE c.code = v_m ->> 'categoria' AND c.is_active) THEN
      RAISE EXCEPTION 'ERR_CATEGORIA_INVALIDA: %', v_m ->> 'categoria';
    END IF;
    IF (v_m ->> 'sentido') NOT IN ('debito', 'credito') THEN
      RAISE EXCEPTION 'ERR_SENTIDO_INVALIDO: %', v_m ->> 'sentido';
    END IF;
    IF coalesce((v_m ->> 'amount')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'ERR_MONTO_INVALIDO: % (el motor prohíbe movimientos <= 0)', v_m ->> 'amount';
    END IF;
  END LOOP;

  -- Partida doble EXIGIDA para toda rectificación (validación previa).
  SELECT coalesce(sum(CASE WHEN m ->> 'sentido' = 'debito'  THEN round((m ->> 'amount')::numeric, 2) ELSE 0 END), 0),
         coalesce(sum(CASE WHEN m ->> 'sentido' = 'credito' THEN round((m ->> 'amount')::numeric, 2) ELSE 0 END), 0)
    INTO v_debit, v_credit
  FROM jsonb_array_elements(p_movements) m;
  IF abs(v_debit - v_credit) > 0.005 THEN
    RAISE EXCEPTION 'ERR_RECTIFICACION_DESQUILIBRADA: débitos=% créditos=%', v_debit, v_credit;
  END IF;

  -- Idempotencia completa: asiento previo en la generación destino.
  SELECT count(*) INTO v_count
  FROM public.fin_entries e
  WHERE e.store_id = p_store_id AND e.generation_id = v_gen
    AND e.document_number = p_document_number AND e.event = 'ajuste_manual';
  IF v_count > 1 THEN
    RAISE EXCEPTION 'ERR_RECTIFICACION_AMBIGUA: % asientos % en la generación %', v_count, p_document_number, v_gen;
  END IF;

  IF v_count = 1 THEN
    SELECT e.id INTO v_entry_id
    FROM public.fin_entries e
    WHERE e.store_id = p_store_id AND e.generation_id = v_gen
      AND e.document_number = p_document_number AND e.event = 'ajuste_manual';

    SELECT count(*),
           coalesce(round(sum(CASE WHEN m.sense = 'debito' THEN m.amount_cup ELSE -m.amount_cup END), 2), 0)
      INTO v_n_mov, v_saldo
    FROM public.fin_movements m WHERE m.entry_id = v_entry_id;
    v_antes := v_n_mov;

    -- Coherencia EXACTA: multiconjunto de movimientos (categoría|sentido|moneda|tasa|importe,
    -- serializado y ordenado) idéntico al esperado. NOTA: paréntesis explícitos —
    -- en PostgreSQL || enlaza más fuerte que ->>, y la cadena sin paréntesis
    -- se parsea como ((... || x) ->> 'sentido') → error text ->> unknown.
    -- P2-review 111: la moneda y la tasa ENTRAN en la firma — un reintento con
    -- mismos importes nominales pero distinta moneda/tasa NO es ya_completa
    -- (el saldo CUP real difiere; sin esto un par equilibrado conservaría el
    -- valor CUP equivocado sin reparación).
    SELECT
      (SELECT string_agg(m.category_code || '|' || m.sense || '|' || m.currency || '|' || round(m.exchange_rate, 6)::text || '|' || round(m.amount, 2)::text, ';'
               ORDER BY m.category_code, m.sense, m.currency, round(m.exchange_rate, 6), round(m.amount, 2))
         FROM public.fin_movements m WHERE m.entry_id = v_entry_id)
      =
      (SELECT string_agg((x ->> 'categoria') || '|' || (x ->> 'sentido') || '|' || coalesce(x ->> 'currency', 'CUP') || '|' || round(coalesce((x ->> 'exchange_rate')::numeric, 1), 6)::text || '|' || round((x ->> 'amount')::numeric, 2)::text, ';'
               ORDER BY x ->> 'categoria', x ->> 'sentido', coalesce(x ->> 'currency', 'CUP'), round(coalesce((x ->> 'exchange_rate')::numeric, 1), 6), round((x ->> 'amount')::numeric, 2))
         FROM jsonb_array_elements(p_movements) AS je(x))
    INTO v_coherente;

    IF v_n_mov >= 1 AND v_coherente AND abs(v_saldo) <= 0.005 THEN
      RETURN jsonb_build_object('status', 'ya_completa', 'entry_id', v_entry_id,
        'generation_id', v_gen, 'movimientos', v_n_mov, 'saldo', v_saldo);
    END IF;

    IF NOT coalesce(p_repair, false) THEN
      RAISE EXCEPTION 'ERR_RECTIFICACION_PARCIAL: asiento % con % movimientos (esperados %, saldo %) — complete o repare con p_repair = true', v_entry_id, v_n_mov, v_expected, v_saldo;
    END IF;

    -- Reparación CONTROLADA (misma transacción): movimientos reemplazados por
    -- los esperados; snapshot actualizado; traza de auditoría obligatoria.
    DELETE FROM public.fin_movements WHERE entry_id = v_entry_id;
    UPDATE public.fin_entries
       SET movements_snapshot = p_movements, description = coalesce(p_description, description)
     WHERE id = v_entry_id;
    FOR t IN SELECT * FROM jsonb_array_elements(p_movements) LOOP
      INSERT INTO public.fin_movements (
        entry_id, store_id, category_code, sense, amount, currency, exchange_rate,
        economic_date, document_number, description, currency_origin, amount_origin, traza)
      VALUES (
        v_entry_id, p_store_id, t ->> 'categoria', t ->> 'sentido', (t ->> 'amount')::numeric,
        coalesce(t ->> 'currency', 'CUP'), coalesce((t ->> 'exchange_rate')::numeric, 1),
        p_economic_date, p_document_number, coalesce(t ->> 'description', p_description),
        t ->> 'currency_origin', (t ->> 'amount_origin')::numeric, coalesce(t -> 'traza', '{}'::jsonb));
    END LOOP;
    SELECT count(*),
           coalesce(round(sum(CASE WHEN m.sense = 'debito' THEN m.amount_cup ELSE -m.amount_cup END), 2), 0)
      INTO v_n_mov, v_saldo
    FROM public.fin_movements m WHERE m.entry_id = v_entry_id;
    IF v_n_mov <> v_expected OR abs(v_saldo) > 0.005 THEN
      RAISE EXCEPTION 'ERR_RECTIFICACION_VERIFICACION: tras reparar quedan %/% movimientos (saldo %)', v_n_mov, v_expected, v_saldo;
    END IF;
    INSERT INTO public.audit_logs (user_id, action, table_name, record_id, old_data, new_data, store_id)
    VALUES (p_user_id, 'SYSTEM_RECTIFICATION_REPAIRED', 'fin_entries', v_entry_id,
            jsonb_build_object('entrada', v_entry_id, 'movimientos_antes', v_antes),
            jsonb_build_object('entry_id', v_entry_id, 'documento', p_document_number,
                               'movimientos', v_expected, 'saldo', v_saldo),
            p_store_id) RETURNING id INTO v_audit;
    RETURN jsonb_build_object('status', 'reparada', 'entry_id', v_entry_id,
      'generation_id', v_gen, 'movimientos', v_n_mov, 'saldo', v_saldo, 'audit_id', v_audit);
  END IF;

  -- Creación ATÓMICA: asiento + TODOS los movimientos en la misma transacción.
  INSERT INTO public.fin_entries (
    store_id, document_type, document_id, document_number, event, payment_ref,
    economic_date, rule_version_id, movements_snapshot, description, created_by, generation_id)
  VALUES (
    p_store_id, p_document_type, NULL, p_document_number, 'ajuste_manual', NULL,
    p_economic_date, NULL, p_movements, p_description, p_user_id, v_gen)
  RETURNING id INTO v_entry_id;

  FOR t IN SELECT * FROM jsonb_array_elements(p_movements) LOOP
    INSERT INTO public.fin_movements (
      entry_id, store_id, category_code, sense, amount, currency, exchange_rate,
      economic_date, document_number, description, currency_origin, amount_origin, traza)
    VALUES (
      v_entry_id, p_store_id, t ->> 'categoria', t ->> 'sentido', (t ->> 'amount')::numeric,
      coalesce(t ->> 'currency', 'CUP'), coalesce((t ->> 'exchange_rate')::numeric, 1),
      p_economic_date, p_document_number, coalesce(t ->> 'description', p_description),
      t ->> 'currency_origin', (t ->> 'amount_origin')::numeric, coalesce(t -> 'traza', '{}'::jsonb));
  END LOOP;

  -- Verificación de partida doble POST-inserción (fallo → revierte TODO).
  SELECT count(*),
         coalesce(round(sum(CASE WHEN m.sense = 'debito' THEN m.amount_cup ELSE -m.amount_cup END), 2), 0)
    INTO v_n_mov, v_saldo
  FROM public.fin_movements m WHERE m.entry_id = v_entry_id;
  IF v_n_mov <> v_expected OR abs(v_saldo) > 0.005 THEN
    RAISE EXCEPTION 'ERR_RECTIFICACION_VERIFICACION: %/% movimientos (saldo %) — transacción revertida', v_n_mov, v_expected, v_saldo;
  END IF;

  -- Documento de auditoría + verificación (misma transacción).
  INSERT INTO public.audit_logs (user_id, action, table_name, record_id, old_data, new_data, store_id)
  VALUES (p_user_id, 'SYSTEM_RECTIFICATION_APPLIED', 'fin_entries', v_entry_id,
          jsonb_build_object('entrada', NULL),
          jsonb_build_object('entry_id', v_entry_id, 'documento', p_document_number,
                             'tipo', p_document_type, 'fecha_economica', p_economic_date,
                             'movimientos', v_expected, 'debitos', v_debit, 'creditos', v_credit),
          p_store_id) RETURNING id INTO v_audit;
  IF v_audit IS NULL THEN
    RAISE EXCEPTION 'ERR_AUDITORIA_FALTANTE: documento de auditoría no insertado';
  END IF;

  RETURN jsonb_build_object('status', 'creada', 'entry_id', v_entry_id,
    'generation_id', v_gen, 'movimientos', v_n_mov, 'saldo', v_saldo, 'audit_id', v_audit);
END

BEGIN
  IF NEW.status = 'completed' AND (TG_OP = 'INSERT' OR OLD.status <> 'completed') THEN
    PERFORM public.fin_post_document_safe('VENTA', NEW.id, 'reconocimiento');
  ELSIF TG_OP = 'UPDATE' AND NEW.status IN ('voided', 'reversed', 'refunded')
        AND OLD.status NOT IN ('voided', 'reversed', 'refunded') THEN
    PERFORM public.fin_post_annulment_safe('VENTA', NEW.id);
  END IF;
  RETURN COALESCE(NEW, OLD);
END

DECLARE
  target_store_id uuid := p_store_id;
BEGIN
  -- Validación de acceso
  IF NOT public.has_management_access_as(auth.uid(), target_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED: Caller must be admin, manager or encargado of the store.';
  END IF;

  -- Activar restore_mode para bypassear triggers de validación
  PERFORM set_config('app.restore_mode', 'true', true);

  BEGIN
    -- ── 1. Datos transaccionales ──
    DELETE FROM payment_transactions WHERE store_id = target_store_id;
    DELETE FROM transaction_items WHERE transaction_id IN (
      SELECT id FROM transactions WHERE store_id = target_store_id
    );
    DELETE FROM transactions WHERE store_id = target_store_id;
    DELETE FROM stock_movements WHERE store_id = target_store_id;
    DELETE FROM inventory_movements WHERE store_id = target_store_id;
    DELETE FROM inventory_adjustments WHERE store_id = target_store_id;
    DELETE FROM receipts WHERE store_id = target_store_id;
    DELETE FROM inventory WHERE store_id = target_store_id;
    DELETE FROM cash_closures WHERE store_id = target_store_id;

    -- ── 2. Catálogo de productos ──
    IF p_keep_catalog THEN
      UPDATE products
      SET
        stock_current = 0,
        cost_average = 0,
        updated_at = NOW()
      WHERE store_id = target_store_id;
    ELSE
      DELETE FROM product_variants WHERE product_id IN (
        SELECT id FROM products WHERE store_id = target_store_id
      );
      DELETE FROM products WHERE store_id = target_store_id;
    END IF;

    -- ── 3. Reconciliación post-restore ──
    -- Después de bypassear triggers, sincronizar products.stock_current
    -- con inventory.quantity. En este punto inventory fue borrado (step 1),
    -- así que todos los productos tendrán stock_current = 0 (correcto para
    -- un reset). La reconciliación es defensiva: si en el futuro se
    -- reconstruye inventory SIN disparar triggers (otro restore), este
    -- código asegura consistencia.
    UPDATE products p
    SET stock_current = COALESCE(
      (SELECT SUM(inv.quantity) FROM inventory inv
       WHERE inv.product_id = p.id AND inv.store_id = p.store_id),
      0
    )
    WHERE p.store_id = target_store_id;

    -- Desactivar restore_mode
    PERFORM set_config('app.restore_mode', 'false', true);

    RAISE NOTICE 'Store % reset completed. Keep catalog: %. Post-restore reconciliation done.', target_store_id, p_keep_catalog;
  EXCEPTION WHEN OTHERS THEN
    -- Asegurar que restore_mode se desactiva incluso si hay error
    PERFORM set_config('app.restore_mode', 'false', true);
    RAISE;
  END;
END;

DECLARE
  v_caller_uid UUID := CASE WHEN auth.role() = 'service_role'
    THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;
  v_validation JSONB;
  v_blockers TEXT;
BEGIN
  IF v_caller_uid IS NULL OR NOT public.has_store_access_as(v_caller_uid, target_store_id) THEN
    RAISE EXCEPTION 'ERR_UNAUTHORIZED';
  END IF;

  -- SECURITY H2: require management role (admin/manager/encargado) for destructive ops
  IF NOT public.has_management_access_as(v_caller_uid, target_store_id) THEN
    RAISE EXCEPTION 'ERR_MANAGEMENT_ACCESS_REQUIRED: reset requires admin/manager/encargado role';
  END IF;

  -- H-016: validar dependencias ANTES del borrado destructivo.
  -- REGLA DELIBERADA (fase0 20260802000001, comentario restaurado 2026-10-21
  -- tras perderse en las re-materializaciones): para reset solo bloquean las
  -- transfers ENTRANTEs (la tienda es destino — el reset de la origen rompería
  -- la transferencia ajena; las SALIENTES se borran con la propia tienda) y
  -- las sesiones de caja abiertas. OTs abiertas, recibos pendientes y
  -- transfers salientes son internas de la tienda que se resetea.
  SELECT * INTO v_validation FROM public.validate_store_can_be_modified(target_store_id, 'reset');
  -- AUDITORÍA 2026-10-21 (trampa de nulidad, endurecimiento defensivo):
  -- `NOT (v_validation->>'can_modify')::boolean` con v_validation NULL o clave
  -- ausente ⇒ NOT NULL ⇒ NULL ⇒ IF saltado ⇒ reset destructivo SIN validación
  -- (fail-open). Hoy no es alcanzable (validate_store_can_be_modified es STABLE
  -- y devuelve exactamente una fila con can_modify presente), pero una guarda
  -- de seguridad no puede depender de un INVARIANTE DE CALLEE. Fail-closed en
  -- DOS niveles:
  --   (a) can_modify INDETERMINABLE (fila ausente o clave ausente) ⇒ rechazo
  --       directo — jamás un reset sin validación verificada;
  --   (b) can_modify=false ⇒ regla documentada (solo transfers_in y
  --       open_cash_sessions bloquean) con EXISTENCE en lugar de mensaje
  --       agregado: un bloqueador del tipo permitido con message NULL también
  --       bloquea (string_agg de NULL devuelve NULL y el guard antiguo
  --       `v_blockers IS NOT NULL AND v_blockers != ''` lo dejaba pasar).
  IF v_validation IS NULL OR (v_validation->>'can_modify') IS NULL THEN
    RAISE EXCEPTION 'ERR_STORE_VALIDATION_UNAVAILABLE: no se pudo validar las dependencias de la tienda (fail-closed)';
  END IF;
  IF NOT (v_validation->>'can_modify')::boolean THEN
    SELECT string_agg(blocker->>'message', '; ')
    INTO v_blockers
    FROM jsonb_array_elements(v_validation->'blockers') AS blocker
    WHERE blocker->>'type' IN ('transfers_in', 'open_cash_sessions');
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_validation->'blockers') AS blocker
      WHERE blocker->>'type' IN ('transfers_in', 'open_cash_sessions')
    ) THEN
      RAISE EXCEPTION 'ERR_STORE_HAS_DEPENDENCIES: %',
        COALESCE(v_blockers, 'transferencias entrantes pendientes o sesiones de caja abiertas');
    END IF;
  END IF;

  -- Enable restore_mode locally so that triggers with bypass pattern allow DELETEs.
  -- This is the canonical pattern for maintenance RPCs (see restore_transaction_snapshot).
  -- The setting is LOCAL to this transaction and does NOT affect other sessions.
  PERFORM set_config('app.restore_mode', 'true', true);

  -- ── 1. Borrar TODAS las tablas operacionales ──

  -- FIX: payment_transactions FIRST (FK ON DELETE RESTRICT to transactions)
  DELETE FROM payment_transactions WHERE store_id = target_store_id;

  -- Hijas de transactions (now safe — payment_transactions already deleted)
  DELETE FROM transaction_items WHERE transaction_id IN (
    SELECT id FROM transactions WHERE store_id = target_store_id
  );
  DELETE FROM transactions WHERE store_id = target_store_id;

  -- Hijas de receipts
  DELETE FROM receipt_items WHERE receipt_id IN (
    SELECT id FROM receipts WHERE store_id = target_store_id
  );
  DELETE FROM receipts WHERE store_id = target_store_id;

  -- Devoluciones
  DELETE FROM devolution_items WHERE devolution_id IN (
    SELECT id FROM devolutions WHERE store_id = target_store_id
  );
  DELETE FROM devolutions WHERE store_id = target_store_id;

  -- Cotizaciones
  DELETE FROM quotation_items WHERE quotation_id IN (
    SELECT id FROM quotations WHERE store_id = target_store_id
  );
  DELETE FROM quotations WHERE store_id = target_store_id;

  -- Clientes
  DELETE FROM customers WHERE store_id = target_store_id;

  -- Bancos
  DELETE FROM bank_statement_items WHERE bank_statement_id IN (
    SELECT id FROM bank_statements WHERE store_id = target_store_id
  );
  DELETE FROM bank_statements WHERE store_id = target_store_id;

  -- Kardex
  DELETE FROM kardex_entries WHERE store_id = target_store_id;

  -- Conteos físicos
  DELETE FROM physical_count_items WHERE count_id IN (
    SELECT id FROM physical_counts WHERE store_id = target_store_id
  );
  DELETE FROM physical_counts WHERE store_id = target_store_id;

  -- Stock movements
  DELETE FROM stock_movements WHERE store_id = target_store_id;

  -- Cash
  DELETE FROM cash_closures WHERE store_id = target_store_id;
  DELETE FROM cash_sessions WHERE store_id = target_store_id;
  DELETE FROM cash_movements WHERE store_id = target_store_id;
  DELETE FROM cash_register_sessions WHERE store_id = target_store_id;

  -- Inventory adjustments
  DELETE FROM inventory_adjustment_items WHERE adjustment_id IN (
    SELECT id FROM inventory_adjustments WHERE store_id = target_store_id
  );
  DELETE FROM inventory_adjustments WHERE store_id = target_store_id;

  -- Transfers
  DELETE FROM transfer_items WHERE transfer_id IN (
    SELECT id FROM transfers WHERE origin_store_id = target_store_id OR destination_store_id = target_store_id
  );
  DELETE FROM transfers WHERE origin_store_id = target_store_id OR destination_store_id = target_store_id;
  DELETE FROM transfer_approval_rules WHERE store_id = target_store_id;

  -- Purchase orders
  DELETE FROM purchase_order_items WHERE po_id IN (
    SELECT id FROM purchase_orders WHERE store_id = target_store_id
  );
  DELETE FROM purchase_orders WHERE store_id = target_store_id;

  -- Production orders
  DELETE FROM production_order_items WHERE order_id IN (
    SELECT id FROM production_orders WHERE store_id = target_store_id
  );
  DELETE FROM production_orders WHERE store_id = target_store_id;

  -- Workers + commissions
  DELETE FROM commission_payments WHERE store_id = target_store_id;
  DELETE FROM commission_rules WHERE store_id = target_store_id;
  DELETE FROM workers WHERE store_id = target_store_id;

  -- Sales transactions (legacy table if exists)
  DELETE FROM sales_transactions WHERE store_id = target_store_id;

  -- Ofertas
  DELETE FROM ofertas WHERE store_id = target_store_id;

  -- Exchange rates
  DELETE FROM store_exchange_rates WHERE store_id = target_store_id;

  -- V4-2 fix: NULLificar category_id antes de borrar categories
  UPDATE products SET category_id = NULL WHERE store_id = target_store_id;
  DELETE FROM suppliers WHERE store_id = target_store_id;
  DELETE FROM categories WHERE store_id = target_store_id;

  -- Warehouse
  DELETE FROM warehouse_stock WHERE store_id = target_store_id;
  DELETE FROM warehouses WHERE store_id = target_store_id;

  -- Inventory
  DELETE FROM inventory WHERE store_id = target_store_id;
  DELETE FROM inventory_batches WHERE store_id = target_store_id;
  DELETE FROM inventory_snapshots WHERE store_id = target_store_id;

  -- Analytics
  DELETE FROM abc_classifications WHERE store_id = target_store_id;
  DELETE FROM price_change_history WHERE store_id = target_store_id;
  DELETE FROM price_commit_log WHERE store_id = target_store_id;
  DELETE FROM tax_configurations WHERE store_id = target_store_id;

  -- Services
  DELETE FROM received_services WHERE store_id = target_store_id;
  DELETE FROM service_types WHERE store_id = target_store_id;

  -- Fiscal
  DELETE FROM fiscal_closings WHERE store_id = target_store_id;

  -- Catalog (conditional)
  IF p_keep_catalog THEN
    UPDATE products SET stock_current = 0, cost_average = 0, updated_at = NOW() WHERE store_id = target_store_id;
    DELETE FROM product_lots WHERE store_id = target_store_id;
  ELSE
    DELETE FROM product_lots WHERE store_id = target_store_id;
    DELETE FROM product_variants WHERE product_id IN (SELECT id FROM products WHERE store_id = target_store_id);
    DELETE FROM product_cost_sheets WHERE store_id = target_store_id;
    DELETE FROM store_cost_templates WHERE store_id = target_store_id;
    DELETE FROM cost_sheet_templates WHERE store_id = target_store_id;
    DELETE FROM products WHERE store_id = target_store_id;
  END IF;

  -- Messaging
  DELETE FROM whatsapp_messages WHERE store_id = target_store_id;
  DELETE FROM whatsapp_invitations WHERE store_id = target_store_id;
  DELETE FROM whatsapp_contacts WHERE store_id = target_store_id;
  DELETE FROM whatsapp_risk_state WHERE store_id = target_store_id;
  DELETE FROM whatsapp_configs WHERE store_id = target_store_id;
  DELETE FROM telegram_messages WHERE store_id = target_store_id;
  DELETE FROM telegram_invitations WHERE store_id = target_store_id;
  DELETE FROM telegram_contacts WHERE store_id = target_store_id;
  DELETE FROM telegram_configs WHERE store_id = target_store_id;

  -- Notifications + snapshots
  DELETE FROM store_notifications WHERE store_id = target_store_id;
  DELETE FROM store_reset_snapshots WHERE store_id = target_store_id;

  -- Audit
  INSERT INTO audit_logs (action, table_name, record_id, store_id, metadata)
  VALUES ('store_reset_completed', 'stores', target_store_id, target_store_id,
    jsonb_build_object('reset_by', v_caller_uid, 'reset_at', now(), 'keep_catalog', p_keep_catalog));
END;
